SELECT percent_rank() OVER (ORDER BY AVG(labevents.value)) AS percentile_rank FROM labevents JOIN icustays ON labevents.subject_id = icustays.subject_id JOIN patients ON icustays.subject_id = patients.subject_id WHERE labevents.itemid = 88679002 AND patients.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) BETWEEN 80 AND 90 AND AVG(labevents.value) <= 88 GROUP BY icustays.subject_id;